const cmMoney=new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'});
function cmData(card){
 const sources=[card?.pricing?.cardmarket,card?.prices?.cardmarket,card?.variants_detailed?.find(v=>v?.pricing?.cardmarket)?.pricing?.cardmarket].filter(Boolean);
 for(const p of sources){
  const trend=Number(p.trend??p.trendPrice);
  const low=Number(p.low??p.lowPrice);
  const avg=Number(p.avg??p.averageSellPrice);
  if(p.trend!=null&&Number.isFinite(trend)&&trend>=0)return {price:trend,type:'Trend',updated:p.updated||null};
  if(p.low!=null&&Number.isFinite(low)&&low>=0)return {price:low,type:'Low',updated:p.updated||null};
  if(p.avg!=null&&Number.isFinite(avg)&&avg>=0)return {price:avg,type:'Average',updated:p.updated||null};
 }
 return null;
}
let cmGeneration=0;
async function hydratePrices(){
 const generation=++cmGeneration;
 const grid=document.querySelector('#groupContainer');
 if(!grid)return;
 let summary=document.getElementById('cmSummary');
 if(!summary){summary=document.createElement('div');summary.id='cmSummary';summary.className='cm-summary';grid.parentElement.insertBefore(summary,grid)}
 summary.innerHTML='<div><b>Cardmarket deck value</b><small>Loading available EUR prices from TCGdex…</small></div><span class="cm-price-loading">Calculating…</span>';
 const entries=currentGroups.flatMap(g=>g.cards);
 const results=await Promise.all(entries.map(async c=>{try{return {c,price:cmData(await getCard(c[2],c[3],c[1]))}}catch{return {c,price:null}}}));
 if(generation!==cmGeneration||!summary.isConnected)return;
 const known=results.filter(x=>x.price),missing=results.filter(x=>!x.price);
 const sum=known.reduce((a,x)=>a+x.price.price*x.c[0],0);
 const dated=known.map(x=>x.price.updated).filter(Boolean).sort();
 const note=missing.length?`${missing.reduce((a,x)=>a+x.c[0],0)} cards have unavailable pricing · partial total`:'All 60 cards priced';
 summary.innerHTML=`<div><b>Cardmarket deck value</b><small>${note}${dated.length?' · Latest source update: '+esc(dated[dated.length-1]):''}</small><small>Uses trend price where available, otherwise low or average. Estimates exclude shipping.</small></div><div><strong>${known.length?cmMoney.format(sum):'Unavailable'}</strong><small>${known.length?'EUR · '+known.reduce((a,x)=>a+x.c[0],0)+' copies priced':'No matching prices returned'}</small><a href="https://www.cardmarket.com/en/Pokemon" target="_blank" rel="noopener">Cardmarket ↗</a></div>`;
 grid.querySelectorAll('.card-item').forEach(el=>{
  const setnum=el.dataset.open;
  const name=el.querySelector('.card-name')?.textContent;
  const match=results.find(x=>x.c[2]+'-'+x.c[3]===setnum&&x.c[1]===name);
  if(!match)return;
  let price=el.querySelector('.cm-price');if(!price){price=document.createElement('span');price.className='cm-price';el.append(price)}
  if(match.price){price.textContent=cmMoney.format(match.price.price)+' / card';price.title=match.price.type+' price'+(match.price.updated?' · Updated '+match.price.updated:'');}
  else{price.textContent='Price unavailable';price.classList.add('missing')}
 });
}
// One shared card-detail dialog for all tournament and archetype decklists.
function cardRulesText(data){
 if(!data)return '';
 const chunks=[];
 for(const ability of (data.abilities||[]))chunks.push(`<div class="card-rule"><strong>${esc(ability.name||'Ability')}</strong><p>${esc(ability.effect||'')}</p></div>`);
 for(const attack of (data.attacks||[]))chunks.push(`<div class="card-rule"><strong>${esc(attack.name||'Attack')}${attack.damage?' · '+esc(attack.damage):''}</strong>${attack.effect?`<p>${esc(attack.effect)}</p>`:''}</div>`);
 if(data.effect)chunks.push(`<div class="card-rule"><strong>Card effect</strong><p>${esc(data.effect)}</p></div>`);
 return chunks.join('');
}
let tournamentDialogRequest=0;
async function openTournamentCard(el){
 const dlg=document.querySelector('#cardDialog'),body=document.querySelector('#dialogBody');if(!dlg||!body)return;
 const name=el.dataset.cardName,set=el.dataset.cardSet,num=el.dataset.cardNumber;
 const c=[Number(el.querySelector('.quantity')?.textContent?.replace(/[^0-9]/g,'')||1),name,set,num];
 const request=++tournamentDialogRequest;
 body.innerHTML=`<div class="modal-layout"><div class="modal-preview">${cardFrame(c,'modal-card')}</div><div><div class="eyebrow small">CARD DETAILS</div><h2>${esc(name)}</h2><p class="muted">${esc(set)} · ${esc(num)}</p><p class="muted">Loading card details…</p></div></div>`;
 if(!dlg.open)dlg.showModal();
 const data=await getCard(set,num,name);
 if(!dlg.open||request!==tournamentDialogRequest)return;
 const link=cardmarketLink(data,c);
 const image=imageUrl(data);
 body.innerHTML=`<div class="modal-layout"><div class="modal-preview">${image?`<img class="modal-image" src="${esc(image)}" alt="${esc(name)} card"/>`:cardFrame(c,'modal-card')}</div><div class="modal-details"><div class="eyebrow small">CARD DETAILS</div><h2>${esc(name)}</h2><p class="muted">${esc(set)} · ${esc(num)} · ${c[0]} ${c[0]===1?'copy':'copies'}</p>${data?.hp?`<p class="muted">${esc(data.hp)} HP</p>`:''}${cardRulesText(data)}<a class="text-link" href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${esc(link.label)}</a></div></div>`;
}
function wireTournamentCardDialog(){
 if(document.body.dataset.tournamentDialogWired)return;
 document.body.dataset.tournamentDialogWired='1';
 document.addEventListener('click',e=>{const card=e.target.closest('.tournament-card');if(card)openTournamentCard(card)});
 document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.tournament-card')){e.preventDefault();openTournamentCard(e.target)}});
}
wireTournamentCardDialog();
// Shared tournament-deck rendering: quantity overlay and Cardmarket valuation.
let tournamentPriceGeneration=0;
function tournamentCardMarkup(c){
 return `<div class="card-item tournament-card" role="button" tabindex="0" aria-label="View card details" data-card-set="${esc(c[2])}" data-card-number="${esc(c[3])}" data-card-name="${esc(c[1])}"><div class="tournament-art-wrap">${cardFrame(c)}<span class="quantity" aria-label="${c[0]} copies">×${c[0]}</span></div><div class="card-info"><strong>${esc(c[1])}</strong><small>${esc(c[2])} ${esc(c[3])}</small><small class="cm-price">Price loading…</small></div></div>`;
}
async function hydrateTournamentPrices(scope){
 const generation=++tournamentPriceGeneration;
 const root=document.querySelector(scope);
 if(!root)return;
 const cards=Array.from(root.querySelectorAll('.tournament-card'));
 if(!cards.length)return;
 let summary=root.querySelector('.cm-summary');
 if(!summary){summary=document.createElement('div');summary.className='cm-summary tournament-cm-summary';const grid=root.querySelector('.card-grid');grid?.parentElement.insertBefore(summary,grid)}
 summary.innerHTML='<div><b>Cardmarket deck value</b><small>Loading available EUR prices from TCGdex…</small></div><span class="cm-price-loading">Calculating…</span>';
 const results=await Promise.all(cards.map(async el=>{
  const qty=Number(el.querySelector('.quantity')?.textContent.replace(/[^0-9]/g,''))||0;
  try{return {el,qty,price:cmData(await getCard(el.dataset.cardSet,el.dataset.cardNumber,el.dataset.cardName))}}catch{return {el,qty,price:null}}
 }));
 if(generation!==tournamentPriceGeneration||!root.isConnected||!summary.isConnected)return;
 const known=results.filter(r=>r.price),pricedCopies=known.reduce((n,r)=>n+r.qty,0);
 const total=known.reduce((n,r)=>n+r.qty*r.price.price,0);
 const missing=results.reduce((n,r)=>n+(r.price?0:r.qty),0);
 summary.innerHTML=`<div><b>Cardmarket deck value</b><small>${missing?`${missing} cards have unavailable pricing · partial total`:'All 60 cards priced'}</small><small>Trend price when available; otherwise low or average. Excludes shipping.</small></div><div><strong>${known.length?cmMoney.format(total):'Unavailable'}</strong><small>${pricedCopies} copies priced · EUR</small><a href="https://www.cardmarket.com/en/Pokemon" target="_blank" rel="noopener noreferrer">Cardmarket ↗</a></div>`;
 for(const r of results){const label=r.el.querySelector('.cm-price');if(!label)continue;label.textContent=r.price?cmMoney.format(r.price.price)+' / card':'Price unavailable';label.classList.toggle('missing',!r.price)}
}
function groupMarkup(){return currentGroups.filter(g=>activeFilter==='All'||g.name===activeFilter).map(g=>`<section class="card-group"><div class="group-heading"><h3>${esc(g.name)} <span>${g.count} CARDS</span></h3><div class="group-rule"></div></div><div class="card-grid">${g.cards.map(c=>`<button class="card-item" data-open="${esc(c[2])}-${esc(c[3])}" aria-label="View ${esc(c[1])}">${cardFrame(c)}<span class="quantity">×${c[0]}</span><span class="card-name">${esc(c[1])}</span>${isBasicEnergy(c[1])?"":`<span class="card-set">${esc(c[2])} · ${esc(c[3])}</span>`}</button>`).join('')}</div></section>`).join('')}
// Card art resolver: exact collector number and name, never a different printing.
// TCGdex uses its own set IDs, which can differ from PTCG Live abbreviations.
const setDetailCache=new Map();
// PTCG Live abbreviations are distinct from TCGdex set IDs.
// These are candidate IDs only; every returned card must match name and collector number.
const setAliases={SVI:['sv01'],PRE:['sv08.5'],PBL:['me05'],WHT:['sv10.5w'],BLK:['sv10.5b'],TWM:['sv06','sv6'],TEF:['sv05','sv5'],SCR:['sv07','sv7'],MEG:['me01'],ASC:['me02.5'],POR:['me03'],MEE:['mee'],SSP:['sv08','sv8'],JTG:['sv09','sv9'],DRI:['sv10'],SFA:['sv06.5','sv6.5'],PFL:['me02'],CRI:['me04'],'30C':['me55']};
const setNames={SVI:['Scarlet & Violet'],PRE:['Prismatic Evolutions'],PBL:['Pitch Black'],WHT:['White Flare'],BLK:['Black Bolt'],TWM:['Twilight Masquerade'],TEF:['Temporal Forces'],SCR:['Stellar Crown'],MEG:['Mega Evolution'],ASC:['Ascended Heroes'],POR:['Phantasmal Flames'],MEE:['Mega Evolution Energy'],SSP:['Surging Sparks'],JTG:['Journey Together'],DRI:['Destined Rivals'],SFA:['Shrouded Fable'],PFL:['Perfect Order'],CRI:['Crimson'],'30C':['30th Celebration']};
// Shared built-in mappings travel with this HTML to every future deck.
// Verified discoveries are also cached locally when browser storage is available.
const SET_MAPPING_CACHE_KEY='deckforge.tcgdex.verified-set-mappings.v1';
let learnedSetAliases={};
try{const saved=JSON.parse(localStorage.getItem(SET_MAPPING_CACHE_KEY)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const [code,ids] of Object.entries(saved)){if(/^[A-Z0-9]{2,8}$/.test(code)&&Array.isArray(ids))learnedSetAliases[code]=ids.filter(id=>typeof id==='string'&&/^[a-z0-9.\-]+$/i.test(id)).slice(0,5)}}catch(e){}
function rememberVerifiedSet(code,id){
 if(!/^[A-Z0-9]{2,8}$/.test(code)||!/^[a-z0-9.\-]+$/i.test(id))return;
 const existing=learnedSetAliases[code]||[];
 if(existing.includes(id))return;
 learnedSetAliases[code]=[id,...existing].slice(0,5);
 try{localStorage.setItem(SET_MAPPING_CACHE_KEY,JSON.stringify(learnedSetAliases))}catch(e){}
}
function verifiedCard(card,id,num,name){
 return !!(card?.image&&sameNumber(card.localId||card.id?.split('-').pop(),num)&&norm(card.name)===norm(name)&&(!card.set?.id||norm(card.set.id)===norm(id)));
}
function norm(v){return String(v||'').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]/g,'')}
function sameNumber(a,b){return String(a||'').replace(/^0+/,'')===String(b||'').replace(/^0+/,'')}
let setIndexPromise;
function getSetIndex(){return setIndexPromise ||= fetch(`${API}/sets`).then(r=>r.ok?r.json():[]).catch(()=>[])}
const BASIC_ENERGY_NAMES=new Set(['Grass Energy','Fire Energy','Water Energy','Lightning Energy','Psychic Energy','Fighting Energy','Darkness Energy','Metal Energy','Fairy Energy']);
function isBasicEnergy(name){return BASIC_ENERGY_NAMES.has(name)}
// User-supplied standard Mega Evolution Basic Energy PNGs, embedded for offline Firefox support.
const STATIC_BASIC_ENERGY_IMAGES={"Grass Energy":"data:image/png;base64,","Fire Energy":"data:image/png;base64,","Water Energy":"data:image/png;base64,","Lightning Energy":"data:image/png;base64,","Psychic Energy":"data:image/png;base64,","Fighting Energy":"data:image/png;base64,","Darkness Energy":"data:image/png;base64,","Metal Energy":"data:image/png;base64,"};
// Exact user-provided PNG scans are embedded: no API or network needed for Basic Energy artwork.
async function getBasicEnergyArt(name){
 const image=STATIC_BASIC_ENERGY_IMAGES[name];
 return image?{name,image,staticEnergy:true}:null;
}
async function getCard(set,num,name){
 // Basic Energy artwork uses embedded user-provided MEE 001–008 scans.
 // Special Energy (e.g. Telepathic Psychic Energy) still uses exact set/number.
 if(isBasicEnergy(name))return getBasicEnergyArt(name);
 const key=`${set}-${num}-${name}`;
 if(cardCache.has(key))return cardCache.get(key);
 const task=(async()=>{
  const aliases=[...(learnedSetAliases[set]||[]),...(setAliases[set]||[]),set.toLowerCase()];
  // Known PTCG Live set codes already have exact TCGdex candidates.
  // Avoid downloading the entire set index for every card on a deck page.
  if(!setAliases[set]?.length){
   const index=await getSetIndex();
   for(const entry of (Array.isArray(index)?index:[])){
    if((setNames[set]||[]).some(n=>norm(entry.name)===norm(n)))aliases.push(entry.id);
   }
  }
  const ids=[...new Set(aliases.filter(Boolean))];
  for(const id of ids){
   for(const n of [...new Set([String(num),String(num).padStart(3,'0')])]){
    try{
     const response=await fetch(`${API}/cards/${encodeURIComponent(id+'-'+n)}`);
     if(!response.ok)continue;
     const card=await response.json();
     // The requested set is already fixed by the endpoint ID; some TCGdex
     // responses omit set.id, so don't reject an otherwise correct match.
     if(verifiedCard(card,id,num,name)){rememberVerifiedSet(set,id);return card;}
    }catch(e){}
   }
  }
  // Only accept name-search results when their ID belongs to an identified set.
  try{
   const response=await fetch(`${API}/cards?name=${encodeURIComponent(name)}`);
   if(response.ok){
    const found=await response.json();
    for(const brief of (Array.isArray(found)?found:[])){
     if(!sameNumber(brief.localId,num)||norm(brief.name)!==norm(name))continue;
     if(!ids.some(id=>brief.id?.toLowerCase().startsWith(id.toLowerCase()+'-')))continue;
     const full=await fetch(`${API}/cards/${encodeURIComponent(brief.id)}`);
     if(full.ok){const card=await full.json();if(verifiedCard(card,brief.id.slice(0,brief.id.lastIndexOf('-')),num,name)){rememberVerifiedSet(set,brief.id.slice(0,brief.id.lastIndexOf('-')));return card}}
    }
   }
  }catch(e){}
  return null;
 })();
 // Do not permanently cache failed lookups: transient API errors should be retryable.
 cardCache.set(key,task);
 task.then(card=>{if(!card&&cardCache.get(key)===task)cardCache.delete(key)},()=>{if(cardCache.get(key)===task)cardCache.delete(key)});
 return task;
}
// Retry only cards whose exact artwork lookup failed. Three retries after the
// initial attempt, with a short backoff; successful cards are never refetched.
const ARTWORK_RETRIES=3;
const artworkWait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function getCardWithRetries(set,num,name,node){
 for(let attempt=0;attempt<=ARTWORK_RETRIES;attempt++){
  if(!node.isConnected)return null;
  if(attempt){
   const status=node.querySelector('.art-status');
   if(status)status.textContent=`Retrying artwork (${attempt}/${ARTWORK_RETRIES})…`;
   await artworkWait(450*attempt);
  }
  let card=null;
  try{card=await getCard(set,num,name)}catch(e){}
  if(card?.image)return card;
  // A missing or failed lookup must not be shared as a permanent cache result.
  cardCache.delete(`${set}-${num}-${name}`);
 }
 return null;
}
function imageUrl(card){return card?.image?(card.staticEnergy?card.image:`${card.image}/high.jpg`):null}
function hydrateImages(){
 for(const node of document.querySelectorAll('[data-card]')){
  if(node.dataset.loading)return;
  node.dataset.loading='1';
  const [set,num]=node.dataset.card.split('-');const name=node.dataset.name;
  getCardWithRetries(set,num,name,node).then(card=>{
   if(!node.isConnected)return;
   if(!card?.image){node.classList.add('unavailable');node.title=isBasicEnergy(name)?`${name} image not available in TCGdex`:`Exact ${name} ${set} ${num} image not available in TCGdex`;return}
   const formats=card.staticEnergy?['']:['/high.jpg','/low.jpg','/high.png','/low.png'];let i=0;
   const img=document.createElement('img');img.alt=isBasicEnergy(name)?name:`${name} (${set} ${num})`;img.loading='lazy';img.decoding='async';if(card.staticEnergy)img.classList.add('static-basic-energy');
   img.onload=()=>node.classList.add('loaded');
   img.onerror=()=>{i++;if(i<formats.length)img.src=card.image+formats[i];else{img.remove();node.classList.add('unavailable')}};
   img.src=card.image+formats[i];node.prepend(img);
  }).catch(()=>node.classList.add('unavailable'));
 }
}

// Copy deck text without triggering a file download. The textarea fallback also
// supports browsers where the async Clipboard API is unavailable or denied.
async function copyDeckToClipboard(text,button){
 const original=button.innerHTML;
 let copied=false;
 if(navigator.clipboard && window.isSecureContext){
  try{await navigator.clipboard.writeText(text);copied=true}catch(error){console.warn('Clipboard API denied; trying selection fallback',error)}
 }
 if(!copied){
  const field=document.createElement('textarea');
  field.value=text;
  field.setAttribute('readonly','');
  field.setAttribute('aria-label','Decklist to copy');
  Object.assign(field.style,{position:'fixed',left:'0',top:'0',width:'1px',height:'1px',opacity:'0',zIndex:'-1'});
  document.body.appendChild(field);
  field.focus();field.select();field.setSelectionRange(0,field.value.length);
  try{copied=document.execCommand('copy')}catch(error){console.warn('Legacy clipboard copy failed',error)}
  field.remove();
 }
 if(copied){
  button.textContent='Copied to clipboard ✓';
  setTimeout(()=>{if(button.isConnected)button.innerHTML=original},2400);
  return;
 }
 // Last resort: show selectable text for manual copying, never download a TXT.
 const dialog=document.createElement('dialog');
 dialog.className='card-dialog';
 dialog.style.cssText='max-width:650px;width:calc(100% - 32px);color:white';
 const heading=document.createElement('h2');heading.textContent='Copy decklist';
 const note=document.createElement('p');note.textContent='Your browser blocked automatic clipboard access. Select the decklist below and copy it manually.';
 const area=document.createElement('textarea');area.value=text;area.readOnly=true;
 area.style.cssText='width:100%;height:280px;padding:12px;background:#10121e;color:white;border:1px solid #606777;border-radius:8px;font:13px/1.5 monospace';
 const close=document.createElement('button');close.className='primary-btn';close.textContent='Close';
 close.addEventListener('click',()=>dialog.close());
 dialog.addEventListener('close',()=>dialog.remove());
 dialog.append(heading,note,area,close);document.body.appendChild(dialog);dialog.showModal();area.focus();area.select();
}
