let importedDeck=null;
function parseDeckText(raw){
 const result=[];let group=null;const errors=[];
 for(const [idx,line0] of raw.split(/\r?\n/).entries()){
  const line=line0.trim();if(!line)continue;
  const head=line.match(/^(Pok[eé]mon|Trainer|Energy)\s*:\s*\d*\s*$/i);
  if(head){const n=head[1].toLowerCase();group={name:n.startsWith('pok')?'Pokémon':n==='trainer'?'Trainer':'Energy',cards:[],count:0};result.push(group);continue}
  const match=line.match(/^(\d+)\s+(.+?)\s+([A-Z0-9]{2,6})\s+(\d+[A-Za-z]?)$/i);
  if(!match||!group){errors.push('Line '+(idx+1)+': '+line);continue}
  const q=Number(match[1]);if(q<1||q>60){errors.push('Line '+(idx+1)+': invalid quantity');continue}
  group.cards.push([q,match[2],match[3].toUpperCase(),match[4]]);group.count+=q;
 }
 const total=result.reduce((sum,g)=>sum+g.count,0);
 return {groups:result,total,errors};
}
