let tournamentIndexCache=null;
const tournamentCacheByFile=new Map();
const tournamentHasList=p=>Array.isArray(p?.decklist)&&p.decklist.length>0&&p.decklist.every(c=>Number(c.quantity)>0&&c.name&&c.set&&c.number)&&p.decklist.reduce((n,c)=>n+Number(c.quantity),0)===60;
async function getTournamentIndex(){
 if(tournamentIndexCache)return tournamentIndexCache;
 const r=await fetch('tournaments/index.json',{cache:'no-store'});
 if(!r.ok)throw Error('Tournament index HTTP '+r.status);
 const data=await r.json();
 if(!Array.isArray(data))throw Error('Invalid tournament index');
 tournamentIndexCache=data;
 return data;
}
async function getTournamentById(id){
 const events=await getTournamentIndex();
 const entry=events.find(e=>String(e.id)===String(id));
 if(!entry)throw Error('Tournament not found');
 const file=String(entry.file||'');
 if(!/^[a-zA-Z0-9_.-]+\.json$/.test(file))throw Error('Invalid tournament file');
 if(tournamentCacheByFile.has(file))return tournamentCacheByFile.get(file);
 const r=await fetch('tournaments/'+file,{cache:'no-store'});
 if(!r.ok)throw Error('Tournament data HTTP '+r.status);
 const event=await r.json();
 if(!Array.isArray(event.standings))throw Error('Invalid tournament standings');
 tournamentCacheByFile.set(file,event);
 return event;
}
function tournamentDisplayName(event){
 const raw=String(event?.name||'').trim();
 if(raw && !/^(?:Regional Championship|Tournament)\\s*#?\\d+$/i.test(raw)){
  const clean=raw.replace(/\\s+[–—-]\\s+Limitless(?:TCG)?\\s*$/i,'').trim();
  const regional=clean.match(/^Regional\\s+(.+)$/i);
  return regional ? `${regional[1]} Regional Championship` : clean;
 }
 const id=String(event?.id||'').replace(/^limitless-/,'');
 const known={'583':'Puebla Regional Championship','582':'Nice Regional Championship','581':'Louisville Regional Championship'};
 return known[id]||raw||'Regional Championship';
}
function tournamentPage(){return `${header()}<main class="ranked-library"><div class="eyebrow">TOURNAMENT ARCHIVE</div><h1>Tournament <em>results.</em></h1><p class="rank-subtitle">Choose a Regional Championship to view confirmed Day 2 players and their published decklists.</p><div id="tournamentResults" class="rank-rows"><p>Loading tournaments…</p></div></main>${footer()}`}
function tournamentSeason(dateString){
 const match=String(dateString||'').match(/^(\d{4})-(\d{2})-(\d{2})/);
 if(!match)return null;
 const year=Number(match[1]),month=Number(match[2]),day=Number(match[3]);
 const parsed=new Date(Date.UTC(year,month-1,day));
 if(parsed.getUTCFullYear()!==year||parsed.getUTCMonth()!==month-1||parsed.getUTCDate()!==day)return null;
 const start=month>=9?year:year-1;
 return {key:String(start),label:`${start}–${start+1}`};
}
function tournamentArchiveRow(e){
 return `<a class="rank-row" style="display:flex;justify-content:space-between;align-items:center;gap:18px;text-decoration:none" href="#/tournament/${encodeURIComponent(e.id)}"><span><strong class="rank-title">${esc(tournamentDisplayName(e))}</strong><small style="display:block;margin-top:6px">${esc(e.date||'Date unavailable')}</small></span><span style="white-space:nowrap">View results ↗</span></a>`;
}
async function wireTournaments(){
 const node=document.getElementById('tournamentResults');
 try{
  const events=await getTournamentIndex();
  if(!node.isConnected)return;
  if(!events.length){node.textContent='No tournaments imported yet. Run the GitHub Actions tournament importer.';return}
  const groups=new Map();
  for(const event of events){
   const season=tournamentSeason(event.date);
   const key=season?.key||'unknown';
   if(!groups.has(key))groups.set(key,{label:season?.label||'Date unavailable',events:[]});
   groups.get(key).events.push(event);
  }
  const keys=[...groups.keys()].sort((a,b)=>a==='unknown'?1:b==='unknown'?-1:Number(b)-Number(a));
  node.innerHTML=keys.map((key,index)=>{
   const group=groups.get(key);
   group.events.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.id).localeCompare(String(a.id)));
   return `<details name="computer-search-seasons" class="season-group" ${index===0?'open':''}><summary class="season-heading"><span><strong>${esc(group.label)} Season</strong><small>${group.events.length} Regional Championship${group.events.length===1?'':'s'}</small></span><span class="season-chevron" aria-hidden="true">⌄</span></summary><div class="season-events">${group.events.map(tournamentArchiveRow).join('')}</div></details>`;
  }).join('');
  // Keep one season expanded even on browsers without native named-details grouping.
  const sections=[...node.querySelectorAll('details.season-group')];
  sections.forEach(section=>section.addEventListener('toggle',()=>{
   if(section.open)sections.forEach(other=>{if(other!==section)other.open=false});
  }));
 }catch(e){if(node.isConnected)node.textContent='Tournament index could not load: '+e.message}
}
